INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','bcm','title','de','Mehr als Zutrittskontrolle') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','bcm','title','en','More than access control') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','bcm','text','de','Das BCM-System von TCS bietet weit mehr als nur klassische Zutrittskontrolle. Es integriert vielfältige Funktionen für ein modernes und vernetztes Gebäudemanagement in einer zentralen, skalierbaren Softwarelösung. Ob die smarte Buchung von Gemeinschaftsräumen, die reibungslose Verwaltung von Parkplätzen oder die digitale Bewohnerinformation – BCM vereint diese Anforderungen effizient und schafft so einen echten Mehrwert für Betreiber, Mitarbeiter und Bewohner.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','bcm','text','en','The BCM system from TCS offers far more than just classic access control. It integrates a wide range of functions for modern, connected building management in a central, scalable software solution. Whether smart booking of communal rooms, smooth management of car parks or digital resident information – BCM efficiently combines these requirements and creates real added value for operators, employees and residents.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active) VALUES ('gebaeudemanagement.root','functions','cards_v1',30,true) ON CONFLICT (page_key, section_key) DO UPDATE SET section_type='cards_v1';
