INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active, parent_section_id) SELECT 'gebaeudemanagement.root','functions__digitaleNamensanzeige','card_v1',10,true,p.id FROM cms_sections p WHERE p.page_key='gebaeudemanagement.root' AND p.section_key='functions' ON CONFLICT (page_key, section_key) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitaleNamensanzeige','title','de','1. Digitale Namensanzeige') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitaleNamensanzeige','title','en','1. Digital name display') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitaleNamensanzeige','description','de','Zentrale und zeitgemäße Verwaltung von Bewohnerdaten: Mit der digitalen Namensverwaltung lassen sich Bewohner- oder Firmennamen in Wohn- und Gewerbebauten modern auf Display-Außenstationen, Etagentastern und Briefkästen anzeigen. Die Verwaltung erfolgt äußerst komfortabel: Über einen browserbasierten Zugriff können Administratoren die digitalen Namensschilder jederzeit aus der Ferne aktualisieren, ohne vor Ort sein zu müssen. An den Briefkästen lässt sich zudem die Entnahmeklappe voll in das System integrieren und sicher über elektronische Schlüssel oder PIN-Codes öffnen.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitaleNamensanzeige','description','en','Central and contemporary management of resident data: with digital name management, resident or company names in residential and commercial buildings can be displayed in a modern way on display outdoor stations, floor buttons and letterboxes. Management is extremely convenient: via browser-based access, administrators can update the digital name plates remotely at any time, without having to be on site. At the letterboxes, the collection flap can also be fully integrated into the system and securely opened via electronic keys or PIN codes.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active, parent_section_id) SELECT 'gebaeudemanagement.root','functions__zufahrtssteuerung','card_v1',20,true,p.id FROM cms_sections p WHERE p.page_key='gebaeudemanagement.root' AND p.section_key='functions' ON CONFLICT (page_key, section_key) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__zufahrtssteuerung','title','de','2. Zufahrtssteuerung und Parkraumüberwachung') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__zufahrtssteuerung','title','en','2. Access control for driveways and car park monitoring') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__zufahrtssteuerung','description','de','Effizientes Parkmanagement ohne Wartezeiten: Das System bietet eine reibungslose Zufahrtskontrolle für Fahrzeuge an Schranken und Toren – ideal für Firmenzufahrten, Logistikzentren oder Mitarbeiterparkplätze. Die Identifikation und Öffnung erfolgt komfortabel über intelligente Kfz-Kennzeichenerkennung (sogar bei Geschwindigkeiten von bis zu 30 km/h), reichweitenstarke UHF-Leser an der Windschutzscheibe oder kopiergeschützte Handsender. Eine spezielle Parking-Zentrale ermöglicht zudem die genaue Zählung von Fahrzeugen in definierten Zonen sowie die Steuerung von Ampelanlagen.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__zufahrtssteuerung','description','en','Efficient parking management without waiting times: the system offers smooth access control for vehicles at barriers and gates – ideal for company driveways, logistics centres or employee car parks. Identification and opening are conveniently handled via intelligent licence plate recognition (even at speeds of up to 30 km/h), long-range UHF readers on the windscreen or copy-protected handheld transmitters. A special parking control unit also enables precise counting of vehicles in defined zones as well as the control of traffic light systems.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active, parent_section_id) SELECT 'gebaeudemanagement.root','functions__digitalSignage','card_v1',30,true,p.id FROM cms_sections p WHERE p.page_key='gebaeudemanagement.root' AND p.section_key='functions' ON CONFLICT (page_key, section_key) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitalSignage','title','de','3. Digitale Informations- und Anzeigesysteme (Digital Signage)') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitalSignage','title','en','3. Digital information and display systems (Digital Signage)') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitalSignage','description','de','Gezielte Kommunikation über smarte Infoboards: Ob in Behörden, Unternehmen, Hotels oder Wohngebäuden: Digitale Infoboards versorgen Besucher, Mitarbeiter und Bewohner gezielt mit wichtigen Informationen. Diese interaktiven Anzeigesysteme lassen sich nahtlos in das Zutrittskontrollsystem integrieren und flexibel personalisieren. So können auf den Bildschirmen beispielsweise Öffnungszeiten, Wegeleitpläne, Veranstaltungskalender, Wetterdaten oder wichtige Mitteilungen der Hausverwaltung dynamisch dargestellt werden.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__digitalSignage','description','en','Targeted communication via smart infoboards: whether in public authorities, companies, hotels or residential buildings: digital infoboards provide visitors, employees and residents with important information in a targeted way. These interactive display systems can be seamlessly integrated into the access control system and flexibly personalised. For example, opening hours, wayfinding plans, event calendars, weather data or important notices from the building management can be dynamically displayed on the screens.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active, parent_section_id) SELECT 'gebaeudemanagement.root','functions__reservierenBuchen','card_v1',40,true,p.id FROM cms_sections p WHERE p.page_key='gebaeudemanagement.root' AND p.section_key='functions' ON CONFLICT (page_key, section_key) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__reservierenBuchen','title','de','4. Reservieren und Buchen') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__reservierenBuchen','title','en','4. Reservation and booking') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__reservierenBuchen','description','de','Automatisiertes Ressourcenmanagement inklusive Zutrittsfreigabe: Das BCM-System umfasst ein intelligentes digitales Buchungssystem, mit dem sich Räume, Services oder Einrichtungen wie Waschsalons und Sporthallen bequem per Smartphone, Desktop-PC oder direkt aus Anwendungen wie Outlook reservieren lassen. Besonders clever: Das System vergibt die Zutrittsrechte exakt für das gewählte Zeitfenster und schaltet bei Bedarf automatisch auch vorgelagerte Zugangspunkte, wie den Haupteingang oder die Parkplatzschranke, für den berechtigten Nutzer frei.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__reservierenBuchen','description','en','Automated resource management including access authorisation: the BCM system includes an intelligent digital booking system that allows rooms, services or facilities such as laundries and sports halls to be conveniently reserved via smartphone, desktop PC or directly from applications such as Outlook. Particularly clever: the system grants access rights precisely for the selected time slot and, if required, also automatically opens upstream access points such as the main entrance or the car park barrier for the authorised user.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_sections (page_key, section_key, section_type, sort_order, is_active, parent_section_id) SELECT 'gebaeudemanagement.root','functions__alarmanlagenkopplung','card_v1',50,true,p.id FROM cms_sections p WHERE p.page_key='gebaeudemanagement.root' AND p.section_key='functions' ON CONFLICT (page_key, section_key) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__alarmanlagenkopplung','title','de','5. Alarmanlagenkopplung') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__alarmanlagenkopplung','title','en','5. Alarm system integration') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__alarmanlagenkopplung','description','de','Vernetzte Sicherheitstechnik für optimalen Schutz: Für ein ganzheitliches Gebäudesicherheitskonzept lässt sich die BCM-Zutrittskontrolle direkt mit bestehenden Einbruchmelde- und Alarmanlagen verbinden. Nutzer können Funktionen wie die Scharf- oder Unscharfschaltung der Alarmanlage bequem über Interaktionen mit den BCM-Lesegeräten oder der Smartphone-App bedienen. Administratoren haben zudem die Möglichkeit, spezifische Alarmzonen zu definieren und eingehende Alarmmeldungen zentral in der BCM-Software zu überwachen.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;
INSERT INTO cms_section_fields (page_key, section_key, field_key, locale, value) VALUES ('gebaeudemanagement.root','functions__alarmanlagenkopplung','description','en','Targeted networked security technology for optimal protection: for a holistic building security concept, BCM access control can be directly connected to existing intrusion detection and alarm systems. Users can conveniently arm and disarm the alarm system via interactions with BCM readers or the smartphone app. Administrators can also define specific alarm zones and centrally monitor incoming alarm messages in the BCM software.') ON CONFLICT (page_key, section_key, field_key, locale) DO NOTHING;